import json, sys

class Solution:
    def validTicTacToe(self, board):
        x = sum(row.count("X") for row in board)
        o = sum(row.count("O") for row in board)
        if o != x and o != x - 1:
            return False
        def win(p):
            for i in range(3):
                if all(board[i][j] == p for j in range(3)): return True
                if all(board[j][i] == p for j in range(3)): return True
            return ((board[0][0] == p and board[1][1] == p and board[2][2] == p) or
                    (board[0][2] == p and board[1][1] == p and board[2][0] == p))
        if win("X") and x != o + 1: return False
        if win("O") and x != o: return False
        return True

