class Solution {
public:
    bool validTicTacToe(vector<string>& board) {
        int x=0,o=0;
        for (auto &row: board) for(char c: row) {
            if(c=='X') ++x;
            if(c=='O') ++o;
        }
        if(o!=x && o!=x-1) return false;
        auto win = [&](char p) {
            for(int i=0;i<3;i++) {
                if(board[i][0]==p && board[i][1]==p && board[i][2]==p) return true;
                if(board[0][i]==p && board[1][i]==p && board[2][i]==p) return true;
