import java.io.*;
import java.util.*;
import java.util.regex.*;
class Solution {
    public boolean validTicTacToe(String[] board) {
        int x=0,o=0;
        for(String row:board) for(char c:row.toCharArray()) {
            if(c=='X') x++;
            if(c=='O') o++;
        }
        if(o!=x && o!=x-1) return false;
        boolean xWin=win(board,'X'), oWin=win(board,'O');
        if(xWin && x!=o+1) return false;
        if(oWin && x!=o) return false;
        return true;
    }
    private boolean win(String[] b,char p) {
        for(int i=0;i<3;i++) {
            if(b[i].charAt(0)==p && b[i].charAt(1)==p && b[i].charAt(2)==p) return true;
            if(b[0].charAt(i)==p && b[1].charAt(i)==p && b[2].charAt(i)==p) return true;
        }
        return (b[0].charAt(0)==p && b[1].charAt(1)==p && b[2].charAt(2)==p) ||
               (b[0].charAt(2)==p && b[1].charAt(1)==p && b[2].charAt(0)==p);
    }
}
public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
        String line=br.readLine();
        Matcher m=Pattern.compile("\"([XO ]{3})\"").matcher(line);
        List<String> rows=new ArrayList<>();
        while(m.find()) rows.add(m.group(1));
        System.out.println(new Solution().validTicTacToe(rows.toArray(new String[0])));
    }
}

